import { describe, expect, it } from 'vitest';
import { cargoLockfileFor, isCargoLockfilePath, meetsCargoRequirement, parseCargoLockfile } from '../../core/cargo-lockfile';

const REGISTRY = 'registry+https://github.com/rust-lang/crates.io-index';

const lock = [
  '# This file is automatically @generated by Cargo.',
  'version = 4',
  '',
  '[[package]]',
  'name = "app"',
  'version = "0.1.0"',
  'dependencies = [',
  ' "serde",',
  ' "rand 0.8.5",',
  ']',
  '',
  '[[package]]',
  'name = "serde"',
  'version = "1.0.200"',
  `source = "${REGISTRY}"`,
  'checksum = "abc"',
  '',
  '[[package]]',
  'name = "rand"',
  'version = "0.8.5"',
  `source = "${REGISTRY}"`,
  '',
  '[[package]]',
  'name = "rand"',
  'version = "0.9.1"',
  'source = "sparse+https://index.crates.io/"',
  '',
  '[[package]]',
  'name = "forked"',
  'version = "2.0.0"',
  'source = "git+https://example.test/forked.git#0123abc"',
].join('\n');

describe('isCargoLockfilePath and cargoLockfileFor', () => {
  it('knows the lockfile at any depth, and takes the workspace root\'s', () => {
    expect(isCargoLockfilePath('crates/app/Cargo.lock')).toBe(true);
    expect(isCargoLockfilePath('Cargo.toml')).toBe(false);
    expect(cargoLockfileFor('crates/app/Cargo.toml', new Set(['Cargo.lock']))).toBe('Cargo.lock');
    expect(cargoLockfileFor('crates/app/Cargo.toml', new Set(['other/Cargo.lock']))).toBeUndefined();
  });
});

describe('Cargo.lock', () => {
  const parsed = parseCargoLockfile('Cargo.lock', lock);

  it('gives a registry crate its locked version', () => {
    expect(parsed.resolve('Cargo.toml', 'serde', '1')).toBe('1.0.200');
    expect(parsed.resolve('Cargo.toml', 'serde', undefined)).toBe('1.0.200');
  });

  it('gives none for a workspace member, a git crate or a crate it does not hold', () => {
    expect(parsed.resolve('Cargo.toml', 'app', undefined)).toBeUndefined();
    expect(parsed.resolve('Cargo.toml', 'forked', '2')).toBeUndefined();
    expect(parsed.resolve('Cargo.toml', 'missing', '1')).toBeUndefined();
  });

  it('gives none for what the manifest says is not crates.io\'s', () => {
    expect(parsed.resolve('Cargo.toml', 'serde', 'git+https://example.test/serde.git')).toBeUndefined();
    expect(parsed.resolve('Cargo.toml', 'serde', 'package:other')).toBeUndefined();
  });

  it('picks between two locked versions by the requirement, and gives none when it cannot tell', () => {
    expect(parsed.resolve('Cargo.toml', 'rand', '0.8')).toBe('0.8.5');
    expect(parsed.resolve('Cargo.toml', 'rand', '^0.9')).toBe('0.9.1');
    expect(parsed.resolve('Cargo.toml', 'rand', '>=0.8')).toBeUndefined();
    expect(parsed.resolve('Cargo.toml', 'rand', undefined)).toBeUndefined();
  });

  it('refuses a text that is not a Cargo lockfile', () => {
    expect(() => parseCargoLockfile('Cargo.lock', '{"lockfileVersion": 3}')).toThrow();
  });
});

describe('meetsCargoRequirement', () => {
  it('reads a caret as Cargo does: the leftmost non-zero part is fixed', () => {
    expect(meetsCargoRequirement('1.9.0', '1.2')).toBe(true);
    expect(meetsCargoRequirement('2.0.0', '^1.2')).toBe(false);
    expect(meetsCargoRequirement('0.8.9', '0.8')).toBe(true);
    expect(meetsCargoRequirement('0.9.0', '0.8')).toBe(false);
    expect(meetsCargoRequirement('0.0.4', '0.0.3')).toBe(false);
  });

  it('reads a tilde, an exact requirement and a star', () => {
    expect(meetsCargoRequirement('1.2.9', '~1.2')).toBe(true);
    expect(meetsCargoRequirement('1.3.0', '~1.2')).toBe(false);
    expect(meetsCargoRequirement('1.2.3', '=1.2.3')).toBe(true);
    expect(meetsCargoRequirement('1.2.4', '=1.2.3')).toBe(false);
    expect(meetsCargoRequirement('9.0.0', '*')).toBe(true);
  });
});
